INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, access_level, status, attribution_type, created_by, updated_by) VALUES ('b3800001-0000-4000-8000-000000000001', 'TUT-KEUANGAN2-001', 'b8888888-8888-8888-8888-888888888888', $txt$Dana Darurat: Cara Mengumpulkannya$txt$, 'dana-darurat-cara-mengumpulkannya', $txt$Panduan praktis membangun dana darurat: berapa idealnya, cara menabung, dan jebakan yang harus dihindari.$txt$, 'id', 8, 'MEMBER', 'DRAFT', 'DEVELOPED_BY', 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'f7125028-187e-44e0-b95b-88b69b8d5c9a') ON CONFLICT (business_code) DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('17e9ac8c-45ee-474f-a82b-625fc23aecc2', 'b3800001-0000-4000-8000-000000000001', 'HEADING', 1, jsonb_build_object('text', $txt$Masalah: Hidup Tanpa Dana Darurat$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('506c7444-c1ce-4b74-a286-efa10b57479f', 'b3800001-0000-4000-8000-000000000001', 'PARAGRAPH', 2, jsonb_build_object('text', $txt$Ban motor pecah di tengah bulan, anak sakit harus ke klinik, atau tiba-tiba dirumahkan dari kerja. Tanpa dana darurat, setiap kejadian tak terduga berubah menjadi krisis: terpaksa berutang dengan bunga tinggi atau menjual barang berharga. Dana darurat adalah bantalan keuangan yang memisahkan "masalah" dari "bencana".$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('cbec68bb-9daa-4360-8964-73c2465c765a', 'b3800001-0000-4000-8000-000000000001', 'HEADING', 3, jsonb_build_object('text', $txt$Penjelasan: Berapa Idealnya Dana Darurat?$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('d9990130-3d3a-45af-8db0-af588550afb6', 'b3800001-0000-4000-8000-000000000001', 'PARAGRAPH', 4, jsonb_build_object('text', $txt$Aturan umum: 3 sampai 6 kali pengeluaran bulanan. Lajang dengan pekerjaan stabil cukup 3 bulan; kepala keluarga atau pekerja lepas sebaiknya 6 bulan. Hitung pengeluaran wajib (makan, kontrakan, transport, cicilan), bukan gaji. Misalnya pengeluaran 3 juta per bulan berarti target 9 sampai 18 juta.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('1e0bbf89-1961-4488-95a0-39e3b6c2dd16', 'b3800001-0000-4000-8000-000000000001', 'HEADING', 5, jsonb_build_object('text', $txt$Alat: Yang Kamu Butuhkan$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('06f66e0d-268b-45b9-a2ad-ba5818e72846', 'b3800001-0000-4000-8000-000000000001', 'LIST', 6, jsonb_build_object('text', $txt$Rekening tabungan terpisah dari rekening belanja harian
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('f5a09246-2455-4f57-8e87-a9a4494da49f', 'b3800001-0000-4000-8000-000000000001', 'HEADING', 7, jsonb_build_object('text', $txt$Langkah: Cara Mengumpulkannya$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('b39c0c02-6d9f-420c-adec-c0cb3d54f96d', 'b3800001-0000-4000-8000-000000000001', 'PARAGRAPH', 8, jsonb_build_object('text', $txt$Pertama, hitung target dana daruratmu dari pengeluaran bulanan. Kedua, mulai dari target kecil dulu: 1 juta pertama. Ketiga, sisihkan 10 sampai 20 persen penghasilan setiap gajian lewat autodebit di tanggal yang sama. Keempat, potong satu pengeluaran bocor (jajan kopi, langganan tak terpakai) dan alihkan ke tabungan. Kelima, masukkan seluruh pemasukan tak terduga (bonus, THR) ke dana darurat sampai target tercapai.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('b7ee8888-01c7-41fb-a9c1-413b86e786c2', 'b3800001-0000-4000-8000-000000000001', 'LIST', 9, jsonb_build_object('text', $txt$Jangan menunggu "sisa" uang: sisihkan di awal bulan
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('5b3ae45b-d612-4951-ab0b-72709c6c7e74', 'b3800001-0000-4000-8000-000000000001', 'HEADING', 10, jsonb_build_object('text', $txt$Risiko: Jebakan yang Harus Dihindari$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('5ada2fd3-f5e3-4c60-878c-193e1448884f', 'b3800001-0000-4000-8000-000000000001', 'PARAGRAPH', 11, jsonb_build_object('text', $txt$Risiko terbesar adalah memakai dana darurat untuk hal yang bukan darurat: diskon besar, gadget baru, atau liburan. Tetapkan definisi darurat sejak awal: kehilangan penghasilan, biaya kesehatan mendesak, atau perbaikan penting yang tidak bisa ditunda. Risiko lain: menyimpan dana darurat di investasi berisiko seperti saham atau kripto yang nilainya bisa turun tepat saat kamu membutuhkannya.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('b5045adf-878e-4268-9e0c-8b2fc0816860', 'b3800001-0000-4000-8000-000000000001', 'PARAGRAPH', 12, jsonb_build_object('text', $txt$Penyelesaian: setelah target tercapai, pertahankan jumlahnya. Jika terpaksa dipakai, prioritaskan mengisi ulang sebelum menabung untuk tujuan lain. Dana darurat bukan garis finis, melainkan sabuk pengaman yang selalu terpasang. Mulai bulan ini: buka rekening terpisah dan jadwalkan autodebit pertamamu.$txt$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, access_level, status, attribution_type, created_by, updated_by) VALUES ('b3800002-0000-4000-8000-000000000002', 'TUT-MASAK6-001', 'b7777777-7777-7777-7777-777777777777', $txt$Bakso Sapi Kenyal: Resep Rumahan$txt$, 'bakso-sapi-kenyal-resep-rumahan', $txt$Resep bakso sapi kenyal ala rumahan: rahasia tekstur, takaran bahan, dan langkah mencetak yang benar.$txt$, 'id', 10, 'MEMBER', 'DRAFT', 'DEVELOPED_BY', 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'f7125028-187e-44e0-b95b-88b69b8d5c9a') ON CONFLICT (business_code) DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('619433ce-26d5-43d9-a6bc-ad5434db8c40', 'b3800002-0000-4000-8000-000000000002', 'HEADING', 1, jsonb_build_object('text', $txt$Masalah: Bakso Keras, Lembek, atau Hambar$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('8e038269-aaaa-4fe8-9522-553782fe8d23', 'b3800002-0000-4000-8000-000000000002', 'PARAGRAPH', 2, jsonb_build_object('text', $txt$Bakso buatan sendiri sering gagal: teksturnya keras seperti karet, atau malah lembek dan mudah hancur, bumbunya tidak meresap. Padahal rahasia bakso kenyal bukan pada alat mahal, melainkan pada tiga hal: suhu bahan, takaran es, dan cara mengaduk adonan.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('c0b2c255-7120-4f1d-b4c0-171d56bf681d', 'b3800002-0000-4000-8000-000000000002', 'HEADING', 3, jsonb_build_object('text', $txt$Penjelasan: Rahasia Kekenyalan Bakso$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('79057b9a-bba6-4c37-b474-d5fe91f836f4', 'b3800002-0000-4000-8000-000000000002', 'PARAGRAPH', 4, jsonb_build_object('text', $txt$Kekenyalan bakso berasal dari protein daging (miosin) yang terlarut oleh garam dan membentuk gel saat dipanaskan. Syaratnya: daging harus dingin (hampir beku), ditambah es batu saat digiling agar suhu adonan tetap rendah, dan diaduk sampai benar-benar kalis dan lengket. Daging hangat membuat lemak meleleh dan tekstur menjadi lembek.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('e3cd58e3-31dc-4ee6-8aec-f469e4ffc3dd', 'b3800002-0000-4000-8000-000000000002', 'HEADING', 5, jsonb_build_object('text', $txt$Bahan dan Alat$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('0a70e810-4c40-4a3c-8b84-805317e4f72b', 'b3800002-0000-4000-8000-000000000002', 'LIST', 6, jsonb_build_object('text', $txt$500 gram daging sapi segar, potong kecil lalu dinginkan hingga hampir beku
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('4103c2e4-bc26-4ae8-8438-ab84c1152ccd', 'b3800002-0000-4000-8000-000000000002', 'HEADING', 7, jsonb_build_object('text', $txt$Langkah Membuat$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('bfc4e103-8691-499f-9b52-463032522cf1', 'b3800002-0000-4000-8000-000000000002', 'LIST', 8, jsonb_build_object('text', $txt$Giling daging dingin bersama es batu hingga halus dan lengket
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('2a767cb2-1464-40aa-a46e-aebae946efcf', 'b3800002-0000-4000-8000-000000000002', 'HEADING', 9, jsonb_build_object('text', $txt$Risiko: Kesalahan Umum$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('43feac8c-35b3-488d-bc36-5f44b28ba521', 'b3800002-0000-4000-8000-000000000002', 'PARAGRAPH', 10, jsonb_build_object('text', $txt$Kesalahan paling fatal adalah mencetak bakso ke air yang mendidih keras: permukaan bakso pecah dan tekstur menjadi kasar. Daging yang tidak dingin juga merusak hasil karena lemak mencair sebelum protein membentuk gel. Jangan menambahkan tepung berlebihan karena bakso menjadi keras dan rasa daging hilang.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('a0356fe5-0206-44db-9729-e4e514058527', 'b3800002-0000-4000-8000-000000000002', 'HEADING', 11, jsonb_build_object('text', $txt$Pemeriksaan Hasil$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('53e163ca-b575-44c5-bc8d-2f6595b83107', 'b3800002-0000-4000-8000-000000000002', 'PARAGRAPH', 12, jsonb_build_object('text', $txt$Bakso yang berhasil: kenyal saat digigit tapi tidak alot, permukaan halus, tidak mudah hancur saat dibelah, dan aroma dagingnya terasa. Simpan bakso matang di freezer hingga 1 bulan. Untuk kuah: rebus tulang sapi dengan bawang putih, merica, dan garam selama minimal 1 jam untuk kaldu yang gurih.$txt$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, access_level, status, attribution_type, created_by, updated_by) VALUES ('b3800003-0000-4000-8000-000000000003', 'EXP-KIMIA6-001', 'c4444444-4444-4444-4444-444444444444', $txt$pH: Skala Keasaman$txt$, 'ph-skala-keasaman', $txt$Mengenal pH: skala 0 sampai 14 yang mengukur keasaman, cara mengukurnya, dan perannya dalam tubuh dan lingkungan.$txt$, 'id', 7, 'MEMBER', 'DRAFT', 'DEVELOPED_BY', 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'f7125028-187e-44e0-b95b-88b69b8d5c9a') ON CONFLICT (business_code) DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('b8cb5773-18ae-4aa7-bf61-ca199452492f', 'b3800003-0000-4000-8000-000000000003', 'HEADING', 1, jsonb_build_object('text', $txt$Apa Itu pH?$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('4126bffa-9960-4ecb-aa06-91ce80fd5bda', 'b3800003-0000-4000-8000-000000000003', 'PARAGRAPH', 2, jsonb_build_object('text', $txt$pH adalah skala yang mengukur seberapa asam atau basa suatu larutan. Konsep ini diperkenalkan oleh kimiawan Denmark Soren Sorensen pada tahun 1909. Secara kimia, pH mengukur konsentrasi ion hidrogen (H+) dalam larutan: semakin banyak ion hidrogen, semakin asam larutan itu.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('998380c8-a2e7-4c96-9558-e861cae10134', 'b3800003-0000-4000-8000-000000000003', 'HEADING', 3, jsonb_build_object('text', $txt$Skala pH 0 sampai 14$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('2c99797e-76d2-4406-9379-b7411ba23288', 'b3800003-0000-4000-8000-000000000003', 'PARAGRAPH', 4, jsonb_build_object('text', $txt$Skala pH berjalan dari 0 hingga 14. Nilai di bawah 7 berarti asam (misalnya air jeruk nipis sekitar pH 2), tepat 7 berarti netral (air murni), dan di atas 7 berarti basa atau alkali (misalnya sabun sekitar pH 9 sampai 10). Skala ini logaritmik: larutan pH 3 sepuluh kali lebih asam daripada pH 4.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('8991b080-349d-497c-ab38-edd5e530bc58', 'b3800003-0000-4000-8000-000000000003', 'HEADING', 5, jsonb_build_object('text', $txt$Mengapa pH Penting?$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('b51ec9f4-c7f7-4a67-a915-50d2af9a0c54', 'b3800003-0000-4000-8000-000000000003', 'LIST', 6, jsonb_build_object('text', $txt$Tubuh manusia: darah dijaga pada pH sekitar 7,4; pergeseran kecil saja bisa berbahaya
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('0c4763f3-85ca-4ac2-b24a-01aedee5c867', 'b3800003-0000-4000-8000-000000000003', 'HEADING', 7, jsonb_build_object('text', $txt$Cara Mengukur pH$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('05c8198b-a0c6-4d6a-8cbe-5a0d905664d2', 'b3800003-0000-4000-8000-000000000003', 'PARAGRAPH', 8, jsonb_build_object('text', $txt$Cara paling sederhana memakai kertas lakmus: berubah merah dalam larutan asam dan biru dalam larutan basa. Kertas indikator universal memberi perkiraan angka lewat perubahan warna. Untuk hasil akurat digunakan pH meter digital yang mengukur tegangan listrik dari elektroda khusus. Di laboratorium sekolah, indikator alami seperti ekstrak bunga telang atau kunyit juga bisa dipakai.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('89e56727-972e-4e23-97f6-112718ea54ec', 'b3800003-0000-4000-8000-000000000003', 'HEADING', 9, jsonb_build_object('text', $txt$pH dalam Kehidupan Sehari-hari$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('c7c2a41e-d08e-409d-a5b3-97e7a14eb7cf', 'b3800003-0000-4000-8000-000000000003', 'PARAGRAPH', 10, jsonb_build_object('text', $txt$Lambung kita sangat asam (pH sekitar 1,5 sampai 2) untuk mencerna makanan dan membunuh kuman. Sabun dan sampo dibuat sedikit basa agar bisa mengangkat minyak. Petani menabur kapur untuk menaikkan pH tanah yang terlalu asam. Bahkan rasa segar buah-buahan berasal dari asam alaminya. Memahami pH berarti memahami bahasa kimia yang bekerja diam-diam di sekitar kita.$txt$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, access_level, status, attribution_type, created_by, updated_by) VALUES ('b3800004-0000-4000-8000-000000000004', 'EXP-SEJARAH6-001', 'c8888888-8888-8888-8888-888888888888', $txt$Runtuhnya Majapahit: Akhir Sebuah Era$txt$, 'runtuhnya-majapahit-akhir-sebuah-era', $txt$Mengapa kerajaan terbesar Nusantara runtuh: perang saudara Paregreg, melemahnya pusat kekuasaan, dan bangkitnya Demak.$txt$, 'id', 8, 'MEMBER', 'DRAFT', 'DEVELOPED_BY', 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'f7125028-187e-44e0-b95b-88b69b8d5c9a') ON CONFLICT (business_code) DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('da5f786f-6dfe-44b6-a940-9abfca49cc29', 'b3800004-0000-4000-8000-000000000004', 'HEADING', 1, jsonb_build_object('text', $txt$Majapahit di Puncaknya$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('cec55a55-ded3-411a-acbb-64ea0aa2a7a4', 'b3800004-0000-4000-8000-000000000004', 'PARAGRAPH', 2, jsonb_build_object('text', $txt$Pada abad ke-14 di bawah Hayam Wuruk dan Mahapatih Gajah Mada, Majapahit menguasai hampir seluruh Nusantara. Sumpah Palapa menjadi simbol ambisi mempersatukan kepulauan. Ibu kota di Trowulan (Mojokerto kini) adalah pusat perdagangan ramai yang dikunjungi pedagang dari India, Tiongkok, dan Asia Tenggara.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('f0d40878-307d-40b4-af13-08a5e020f2ce', 'b3800004-0000-4000-8000-000000000004', 'HEADING', 3, jsonb_build_object('text', $txt$Tanda-tanda Keruntuhan$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('f2e4b659-56cb-45a0-89c9-80032dd1bc92', 'b3800004-0000-4000-8000-000000000004', 'PARAGRAPH', 4, jsonb_build_object('text', $txt$Setelah Hayam Wuruk wafat pada 1389, tidak ada lagi pemimpin sekuat dia. Perebutan takhta memecah istana menjadi kubu-kubu. Puncak krisis adalah Perang Paregreg (1404-1406), perang saudara antara Wikramawardhana dan Bhre Wirabhumi yang menewaskan banyak bangsawan dan menguras kekuatan kerajaan.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('e2ff2b61-bf67-47fa-9fbd-3cb0d8d87940', 'b3800004-0000-4000-8000-000000000004', 'HEADING', 5, jsonb_build_object('text', $txt$Faktor Internal$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('4936345f-db02-4100-bc9f-a47f036e9e6a', 'b3800004-0000-4000-8000-000000000004', 'LIST', 6, jsonb_build_object('text', $txt$Perebutan kekuasaan berulang di kalangan keluarga istana
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('50823d1c-8409-490a-85b2-c9e61af5dfce', 'b3800004-0000-4000-8000-000000000004', 'HEADING', 7, jsonb_build_object('text', $txt$Faktor Eksternal$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('db59b374-4cf3-4e0c-aecc-1df9c6134b75', 'b3800004-0000-4000-8000-000000000004', 'PARAGRAPH', 8, jsonb_build_object('text', $txt$Di pesisir utara Jawa, kota-kota pelabuhan Islam seperti Demak semakin kaya dari perdagangan dan semakin berpengaruh secara politik. Ketika pusat Majapahit melemah, Demak di bawah Raden Patah bangkit dan akhirnya menaklukkan sisa-sisa kekuasaan Majapahit pada awal abad ke-16. Jalur perdagangan pun bergeser dari pedalaman ke pesisir.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('b31958d9-5bca-4d23-8957-07804a0c12ed', 'b3800004-0000-4000-8000-000000000004', 'HEADING', 9, jsonb_build_object('text', $txt$Akhir Sebuah Era$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('be71e335-3f4a-4370-bbab-f53ed7a049bb', 'b3800004-0000-4000-8000-000000000004', 'PARAGRAPH', 10, jsonb_build_object('text', $txt$Majapahit tidak runtuh dalam satu hari, melainkan memudar perlahan selama hampir satu abad. Warisannya tetap hidup: konsep Nusantara sebagai gagasan persatuan kepulauan, karya sastra seperti Negarakertagama, dan sistem administrasi yang memengaruhi kerajaan-kerajaan sesudahnya. Runtuhnya Majapahit menandai berakhirnya era kerajaan Hindu-Buddha besar dan dimulainya era kesultanan Islam di Jawa.$txt$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, access_level, status, attribution_type, created_by, updated_by) VALUES ('b3800005-0000-4000-8000-000000000005', 'SCH-SMA-EKO3-001', 'd5555555-5555-5555-5555-555555555555', $txt$Ekonomi Kelas 12: Akuntansi Dasar$txt$, 'ekonomi-kelas-12-akuntansi-dasar', $txt$Materi akuntansi dasar kelas 12: pengertian, persamaan dasar akuntansi, contoh transaksi, latihan soal dan kunci jawaban.$txt$, 'id', 12, 'MEMBER', 'DRAFT', 'DEVELOPED_BY', 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'f7125028-187e-44e0-b95b-88b69b8d5c9a') ON CONFLICT (business_code) DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('8f9ae999-75fb-44f4-a6cd-e41e9fc6d9c4', 'b3800005-0000-4000-8000-000000000005', 'HEADING', 1, jsonb_build_object('text', $txt$Tujuan Pembelajaran$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('6f41e61c-df12-4f93-9c25-09d3bb2acdff', 'b3800005-0000-4000-8000-000000000005', 'PARAGRAPH', 2, jsonb_build_object('text', $txt$Setelah mempelajari bab ini, kamu diharapkan mampu: (1) menjelaskan pengertian dan fungsi akuntansi, (2) menyebutkan persamaan dasar akuntansi, (3) menganalisis pengaruh transaksi terhadap persamaan dasar akuntansi, dan (4) menyusun contoh sederhana pencatatan transaksi.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('be145773-c19c-426d-8c31-70828c8b3f0a', 'b3800005-0000-4000-8000-000000000005', 'HEADING', 3, jsonb_build_object('text', $txt$Pengertian Akuntansi$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('bef48d52-87f4-4f23-ab1a-2e27eae90b0c', 'b3800005-0000-4000-8000-000000000005', 'PARAGRAPH', 4, jsonb_build_object('text', $txt$Akuntansi adalah seni mencatat, mengklasifikasi, dan menyimpulkan transaksi keuangan dalam bentuk laporan yang dapat dipertanggungjawabkan. Akuntansi sering disebut "bahasa bisnis" karena melaluinya pemilik usaha, investor, dan pemerintah dapat memahami kondisi keuangan suatu perusahaan. Fungsi utamanya: menyediakan informasi untuk pengambilan keputusan.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('cef65682-c28a-43b0-95c2-6d1495280eab', 'b3800005-0000-4000-8000-000000000005', 'HEADING', 5, jsonb_build_object('text', $txt$Persamaan Dasar Akuntansi$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('bbee0f05-73d0-484b-b9d8-658e30241c35', 'b3800005-0000-4000-8000-000000000005', 'PARAGRAPH', 6, jsonb_build_object('text', $txt$Persamaan dasar akuntansi adalah: ASET = LIABILITAS + EKUITAS. Aset adalah harta yang dimiliki perusahaan (kas, piutang, peralatan). Liabilitas adalah utang atau kewajiban kepada pihak lain. Ekuitas adalah hak pemilik atas aset setelah dikurangi liabilitas (modal). Setiap transaksi selalu memengaruhi minimal dua unsur sehingga persamaan tetap seimbang.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('0198d7c6-7d8a-4c16-9c7e-e44f1021f7cf', 'b3800005-0000-4000-8000-000000000005', 'HEADING', 7, jsonb_build_object('text', $txt$Contoh Penerapan$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('595d67cd-9ca2-425a-a6a7-819658aa0322', 'b3800005-0000-4000-8000-000000000005', 'PARAGRAPH', 8, jsonb_build_object('text', $txt$Contoh 1: Budi menyetor modal Rp10.000.000 ke usahanya. Aset (kas) bertambah Rp10.000.000, ekuitas (modal) bertambah Rp10.000.000. Contoh 2: usaha membeli peralatan Rp3.000.000 secara tunai. Kas berkurang Rp3.000.000, peralatan bertambah Rp3.000.000; total aset tetap. Contoh 3: usaha berutang ke bank Rp5.000.000. Kas bertambah Rp5.000.000, liabilitas bertambah Rp5.000.000.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('712414ac-5178-4b9d-8583-e735ffe72133', 'b3800005-0000-4000-8000-000000000005', 'HEADING', 9, jsonb_build_object('text', $txt$Latihan Soal$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('a20b7400-a08b-4963-90a8-9ef4c9b5c883', 'b3800005-0000-4000-8000-000000000005', 'LIST', 10, jsonb_build_object('text', $txt$1. Jelaskan perbedaan aset, liabilitas, dan ekuitas beserta masing-masing satu contoh!
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('364f4711-56ed-4e38-b674-a40fdff4867d', 'b3800005-0000-4000-8000-000000000005', 'HEADING', 11, jsonb_build_object('text', $txt$Kunci Jawaban$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('56cdcf3e-fea5-4809-8cde-501f6ae68d53', 'b3800005-0000-4000-8000-000000000005', 'LIST', 12, jsonb_build_object('text', $txt$1. Aset: harta milik perusahaan (contoh: kas, gedung). Liabilitas: kewajiban/utang (contoh: utang bank). Ekuitas: hak pemilik (contoh: modal).
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, access_level, status, attribution_type, created_by, updated_by) VALUES ('b3800006-0000-4000-8000-000000000006', 'SCH-SD-MAT9-001', 'd3333333-3333-3333-3333-333333333333', $txt$Matematika Kelas 4: Pecahan$txt$, 'matematika-kelas-4-pecahan', $txt$Materi pecahan kelas 4 SD: pengertian, pembilang dan penyebut, jenis pecahan, membandingkan, latihan dan kunci jawaban.$txt$, 'id', 10, 'MEMBER', 'DRAFT', 'DEVELOPED_BY', 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'f7125028-187e-44e0-b95b-88b69b8d5c9a') ON CONFLICT (business_code) DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('ea6dd333-e6e3-49a2-95c5-c6034686d433', 'b3800006-0000-4000-8000-000000000006', 'HEADING', 1, jsonb_build_object('text', $txt$Tujuan Pembelajaran$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('916b6cbc-7e3d-4d75-a44b-82d728471655', 'b3800006-0000-4000-8000-000000000006', 'PARAGRAPH', 2, jsonb_build_object('text', $txt$Setelah belajar bab ini, kamu bisa: (1) menjelaskan arti pecahan, (2) menyebutkan pembilang dan penyebut, (3) mengenal jenis-jenis pecahan, dan (4) membandingkan dua pecahan sederhana. Siapkan pensil dan kertas ya, kita belajar sambil berlatih!$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('bbc6d102-770f-4441-9e68-f03a3848d29b', 'b3800006-0000-4000-8000-000000000006', 'HEADING', 3, jsonb_build_object('text', $txt$Pengertian Pecahan$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('8bc66940-c618-417d-b410-57807752d3fa', 'b3800006-0000-4000-8000-000000000006', 'PARAGRAPH', 4, jsonb_build_object('text', $txt$Pecahan adalah bagian dari keseluruhan yang utuh. Bayangkan satu pizza dipotong menjadi 4 bagian sama besar, lalu kamu makan 1 potong. Bagian yang kamu makan ditulis sebagai 1/4 (dibaca: seperempat). Angka 1 disebut pembilang (bagian yang diambil), angka 4 disebut penyebut (jumlah seluruh bagian).$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('d07eec17-a3a4-4d2d-80bb-f7024c6bc4fe', 'b3800006-0000-4000-8000-000000000006', 'HEADING', 5, jsonb_build_object('text', $txt$Jenis-jenis Pecahan$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('0c2d3284-4daf-433b-8178-1ab17f5c58cb', 'b3800006-0000-4000-8000-000000000006', 'LIST', 6, jsonb_build_object('text', $txt$Pecahan biasa: pembilang lebih kecil dari penyebut, contoh 2/5
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('ae192d9d-716b-40ef-b35a-66d12348d177', 'b3800006-0000-4000-8000-000000000006', 'HEADING', 7, jsonb_build_object('text', $txt$Membandingkan Pecahan$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('840e8b66-8bc3-4242-8eaf-8fdcf3ff20e0', 'b3800006-0000-4000-8000-000000000006', 'PARAGRAPH', 8, jsonb_build_object('text', $txt$Jika penyebutnya sama, pecahan dengan pembilang lebih besar nilainya lebih besar: 3/8 lebih besar dari 2/8. Jika pembilangnya sama, pecahan dengan penyebut lebih kecil nilainya lebih besar: 1/2 lebih besar dari 1/4, karena potongannya lebih besar. Coba gambar lingkaran yang dibagi-bagi untuk melihatnya dengan jelas!$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('956d5150-6f30-4f1c-ad11-42e68b66bfef', 'b3800006-0000-4000-8000-000000000006', 'HEADING', 9, jsonb_build_object('text', $txt$Latihan Soal$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES ('055db9da-5b15-4b81-9625-0c864eb2b371', 'b3800006-0000-4000-8000-000000000006', 'LIST', 10, jsonb_build_object('text', $txt$1. Ibu memotong semangka menjadi 8 bagian sama besar. Adi makan 3 bagian. Tuliskan pecahannya dan sebutkan pembilang serta penyebutnya!
